mapper.select:
SELECT id,created_at AS occurred_at FROM training_answer
WHERE owner_id=#{owner} AND created_at>=#{startAt} AND created_at<#{observedUntil}

  AND (created_at<#{afterAt} OR (created_at=#{afterAt} AND id>#{afterId}))

ORDER BY created_at DESC,id ASC LIMIT #{limit}

SELECT refs.item_id,refs.version_id,k.kind,k.status,k.current_version_id, v.id AS fixed_version_id,p.id AS current_version_exists_id, CASE WHEN v.id IS NULL OR p.id IS NULL THEN NULL ELSE CAST(v.body AS BINARY)<>CAST(p.body AS BINARY) END AS body_changed FROM (
SELECT #{ref.itemId} AS item_id,#{ref.versionId} AS version_id
) AS refs LEFT JOIN knowledge_item k ON k.owner_id=#{owner} AND k.id=refs.item_id LEFT JOIN knowledge_version v ON v.owner_id=#{owner} AND v.item_id=refs.item_id AND v.id=refs.version_id LEFT JOIN knowledge_version p ON p.owner_id=k.owner_id AND p.item_id=k.id AND p.id=k.current_version_id
